CREATE TABLE scan_manifest (scan_id TEXT PRIMARY KEY, repo TEXT NOT NULL, commit_sha TEXT NOT NULL, scanner_version TEXT NOT NULL, scanned_at TEXT NOT NULL, analysis_level TEXT NOT NULL, build_status TEXT NOT NULL, manifest_json TEXT NOT NULL);
CREATE TABLE facts (fact_id TEXT PRIMARY KEY, scan_id TEXT NOT NULL, repo TEXT NOT NULL, commit_sha TEXT NOT NULL, project_path TEXT, fact_type TEXT NOT NULL, rule_id TEXT NOT NULL, evidence_tier TEXT NOT NULL, source_symbol TEXT, target_symbol TEXT, contract_element TEXT, file_path TEXT NOT NULL, start_line INTEGER NOT NULL, end_line INTEGER NOT NULL, snippet_hash TEXT, extractor_id TEXT NOT NULL, extractor_version TEXT NOT NULL, properties_json TEXT NOT NULL);
